/**
 * Real-database test harness (no mocks of persistence).
 *
 * Default (your machine / CI):   set TEST_DATABASE_URL to a DISPOSABLE Postgres database.
 *   The schema is dropped and rebuilt with `prisma migrate deploy`, and the normal
 *   `@prisma/client` is used.
 * Sandbox-only mode (SAMAYAK_TEST_DRIVER=wasm): the native Prisma engine cannot be
 *   downloaded, so a WASM-engine client generated by backend/.scratch/regen.sh is used with
 *   TEST_DATABASE_ADMIN_URL (a superuser URL) to create a throw-away database per test file.
 *   Migrations are applied with psql from prisma/migrations.
 */
import { execSync } from "child_process";
import { createRequire } from "module";
import fs from "fs";
import path from "path";

const require_ = createRequire(__filename);
const root = path.resolve(__dirname, "../..");

export interface TestDb {
  url: string;
  prisma: any;
  close: () => Promise<void>;
}

function migrationFiles(): string[] {
  const dir = path.join(root, "prisma/migrations");
  return fs
    .readdirSync(dir)
    .filter((d) => fs.statSync(path.join(dir, d)).isDirectory())
    .sort()
    .map((d) => path.join(dir, d, "migration.sql"));
}

export async function createTestDb(): Promise<TestDb> {
  if (process.env.SAMAYAK_TEST_DRIVER === "wasm") {
    const admin = process.env.TEST_DATABASE_ADMIN_URL ?? "postgresql://postgres@localhost:5433/postgres";
    const name = `samayak_t_${process.pid}_${Date.now().toString(36)}`;
    const u = new URL(admin);
    u.pathname = `/${name}`;
    execSync(`psql "${admin}" -v ON_ERROR_STOP=1 -qc 'CREATE DATABASE ${name}'`);
    for (const f of migrationFiles()) execSync(`psql "${u.toString()}" -v ON_ERROR_STOP=1 -q -f "${f}"`, { stdio: "pipe" });
    const { PrismaClient } = require_(path.join(root, ".scratch/client/wasm.js"));
    const { PrismaPg } = require_("@prisma/adapter-pg");
    const { Pool } = require_("pg");
    const pool = new Pool({ connectionString: u.toString(), max: 8 });
    const prisma = new PrismaClient({ adapter: new PrismaPg(pool) });
    return {
      url: u.toString(),
      prisma,
      close: async () => {
        await prisma.$disconnect();
        await pool.end();
        execSync(`psql "${admin}" -qc 'DROP DATABASE IF EXISTS ${name} WITH (FORCE)'`);
      },
    };
  }

  const url = process.env.TEST_DATABASE_URL;
  if (!url) throw new Error("Set TEST_DATABASE_URL to a disposable Postgres database to run the integration tests");
  const { PrismaClient } = require_("@prisma/client");
  const prisma = new PrismaClient({ datasources: { db: { url } } });
  await prisma.$executeRawUnsafe("DROP SCHEMA IF EXISTS public CASCADE");
  await prisma.$executeRawUnsafe("CREATE SCHEMA public");
  execSync("npx prisma migrate deploy", { cwd: root, env: { ...process.env, DATABASE_URL: url }, stdio: "pipe" });
  return { url, prisma, close: () => prisma.$disconnect() };
}

/** Use inside vi.mock("../../src/lib/prisma", ...) so application code talks to the test database. */
export const testDbRef: { db?: TestDb } = {};
